import { useState, useEffect } from 'react';
import { BASE } from '../../../api/seoApi';

const CHECK = (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
    <path
      d="M13.5 4L6 11.5L2.5 8"
      stroke="var(--aeo-check)"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const FALLBACK_PLANS = [
  {
    name: 'Starter',
    quota: '5 prompts / mo',
    desc: 'For founders putting AI search on the map.',
    price: 50,
    popular: false,
    features: [
      '1 domain · 5 tracked prompts',
      'Weekly 3 posts on Facebook, Instagram, LinkedIn & Google My Business',
      'Monthly AEO / SEO audit',
      'Technical site audit',
      'Competitor analysis',
    ],
  },
  {
    name: 'Growth',
    quota: '15 prompts / mo',
    desc: 'For marketing teams shipping content weekly.',
    price: 150,
    popular: true,
    features: [
      '1 domain · 15 tracked prompts',
      'Weekly 7 posts on Facebook, Instagram, LinkedIn & Google My Business',
      'Competitor analysis',
      'Technical site audit',
      'Automated audit fixes on site',
      'Monthly 2 videos / reels',
      'Weekly 2 blogs',
    ],
  },
  {
    name: 'Scale',
    quota: '15 prompts / mo',
    desc: 'For agencies and multi-brand portfolios.',
    price: 500,
    popular: false,
    features: [
      '4 domains · 15 tracked prompts',
      'Weekly 7 posts on Facebook, Instagram, LinkedIn & Google My Business',
      'Competitor analysis',
      'Technical site audit',
      'Automated audit fixes on site',
      'Monthly 2 videos / reels',
      'Weekly 2 blogs',
    ],
  },
];

export default function Pricing({ onStartTrial, initialPlans }) {
  const [plans, setPlans] = useState(initialPlans || null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (initialPlans) return;

    fetch(`${BASE}/payment/plans`)
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error(`status ${res.status}`))))
      .then((data) => setPlans(data.plans || []))
      .catch((err) => {
        console.error('[Pricing] Could not load plans from', `${BASE}/payment/plans`, '—', err.message);
        setError(true);
      });
    // eslint-disable-next-line
  }, []);

  if (error || (plans && plans.length === 0)) return null;

  const displayPlans = (plans && plans.length > 0 ? plans : initialPlans && initialPlans.length > 0 ? initialPlans : FALLBACK_PLANS).map((plan) => {
    const price = Number(plan.amount ?? plan.price ?? 0);
    const features = Array.isArray(plan.features) ? plan.features : [];
    const quota = plan.prompts ? `${plan.prompts} prompts / mo` : plan.quota || 'Custom plan';
    const description = plan.blurb || plan.desc || 'Flexible plan for your publishing goals.';
    const isPopular = Boolean(plan.highlight ?? plan.popular);

    return {
      id: plan.plan_id || plan.name,
      name: plan.name,
      quota,
      desc: description,
      price,
      popular: isPopular,
      features,
    };
  });

  return (
    <div className="aeo-pricing" id="pricing">
      <style>{STYLES}</style>

      <div className="aeo-pricing__wrap">
        <div className="aeo-pricing__head">
          <span className="aeo-pricing__eyebrow">AEO App Plans</span>
          <h1 className="aeo-pricing__title">Pricing built around how often you publish</h1>
          <p className="aeo-pricing__sub">
            Every plan tracks your AI-search visibility and ships content automatically. Pick the cadence
            that matches your team.
          </p>
        </div>

        <div className="aeo-pricing__grid">
          {displayPlans.map((plan) => (
            <div
              key={plan.id}
              className={'aeo-pricing__card' + (plan.popular ? ' aeo-pricing__card--pop' : '')}
            >
              {plan.popular && <span className="aeo-pricing__badge">Most popular</span>}

              <div className="aeo-pricing__tier">{plan.name}</div>
              <span className="aeo-pricing__quota">{plan.quota}</span>
              <p className="aeo-pricing__desc">{plan.desc}</p>

              <div className="aeo-pricing__price-row">
                <span className="aeo-pricing__currency">S$</span>
                <span className="aeo-pricing__amount">{Math.round(plan.price)}</span>
                <span className="aeo-pricing__period">/ mo</span>
              </div>
              <div className="aeo-pricing__billed">billed annually</div>

              <hr className="aeo-pricing__divider" />

              <ul className="aeo-pricing__features">
                {plan.features.map((feature) => (
                  <li key={feature}>
                    {CHECK}
                    <span>{feature}</span>
                  </li>
                ))}
              </ul>

              <button
                type="button"
                className={'aeo-pricing__cta' + (plan.popular ? ' aeo-pricing__cta--primary' : '')}
                onClick={() => onStartTrial?.(plan.id)}
              >
                Start 14-day trial <span aria-hidden="true">→</span>
              </button>
            </div>
          ))}
        </div>

        <p className="aeo-pricing__foot">
          Need SSO, SOC2, on-prem or volume pricing?{' '}
          <a href="#contact">Talk to sales <span aria-hidden="true">→</span></a>
        </p>
      </div>
    </div>
  );
}

